mapper.select:
SELECT

FROM CUST_CLAIM
WHERE cust_id = #{custId}
  AND org_id = #{orgId}
LIMIT 1

SELECT cm.id, cm.cust_no, cm.cust_name, cm.unified_credit_code, cm.contact_person, cm.contact_mobile, cm.industry, cm.group_type, cm.customer_type, cm.is_keystone, cm.enterprise_type, cm.group_name, cm.is_account_opened, cm.customer_desc, cm.credit_amount, cm.credit_exposure_amount, cm.owner_org_id, cm.lead_id, cm.status, cm.deleted, cm.created_time, cm.updated_time FROM CUST_MASTER cm LEFT JOIN CUST_CLAIM cc ON cc.cust_id = cm.id AND cc.claim_status = 'CLAIMED' WHERE cm.deleted = 0 AND cm.status = 'ACTIVE' AND cc.id IS NULL
AND cm.cust_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY cm.created_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM CUST_CLAIM
WHERE maintainer_emp_id = #{empId}
  AND claim_status = 'CLAIMED'

SELECT COUNT(*) FROM CUST_CLAIM
WHERE org_id = #{orgCode}
  AND claim_status = 'CLAIMED'
